import{_ as r,l as i,o as a,c as l,v as o,p as n,x as d,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"加载与动态链接","description":"","frontmatter":{"title":"加载与动态链接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/load-dynlink.md","filePath":"cs/load-dynlink.md","lastUpdated":1789023840000}'),h={name:"cs/load-dynlink.md"};function T(E,e,_,m,A,P){const t=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="加载与动态链接" tabindex="-1">加载与动态链接 <a class="header-anchor" href="#加载与动态链接" aria-label="Permalink to &quot;加载与动态链接&quot;">​</a></h1><div class="epigraph"><p>可执行文件进内存时，加载器映射节并可能再跑一遍重定位；共享库通过 GOT/PLT 把符号绑定推迟到加载或首次调用。</p><footer>—— 据 Levine, Linkers and Loaders, 2000；ELF 与 System V ABI 整理</footer></div><p>上一课<a href="/cs/got-plt">GOT 与 PLT</a>把静态符号填成地址。许多程序还依赖共享库：<code>libc</code> 不进每个可执行文件。本课不重做 <code>ld</code> 的节合并。缺口是：<strong>加载</strong>（把文件变成进程里的映像）与<strong>动态链接</strong>（运行时解析）。进程映像的操作系统细节下一课程才展开；本课从编译产物一侧讲 GOT/PLT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态链接体积大、修 bug 要重链所有程序。动态：可执行文件带着对 <code>printf</code> 的未决引用。加载时：内核（或用户加载器）按 ELF 程序头 <code>mmap</code> 各段，解释器（<code>ld.so</code>）登场，把依赖库映射进地址空间，填 GOT。延迟绑定：PLT 桩第一次跳进解析器，再改 GOT，其后直跳。</p><p><a href="/cs/paging-vm">虚拟内存分页</a>让不同进程共享库的只读页；本课只要「映射 + 再重定位」，不写缺页。</p><h3 id="动态不是「不链接」" tabindex="-1">动态不是「不链接」 <a class="header-anchor" href="#动态不是「不链接」" aria-label="Permalink to &quot;动态不是「不链接」&quot;">​</a></h3><p>仍要解析符号，只是时刻从编译期挪到加载/首次调用。ABI 仍必须一致：库与可执行文件同一份 psABI，否则参数寄存器错位。</p><p><span class="marginnote">Levine《Linkers and Loaders》给 GOT/PLT 图。ELF <code>DT_NEEDED</code>、<code>R_*_JUMP_SLOT</code> 是机制名字。本课不写动态节全部标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行：内核读入口，若有 <code>PT_INTERP</code> 则先跑动态链接器。链接器：广度加载依赖、重定位相对型、处理 <code>BIND_NOW</code> 或懒绑定。然后跳到用户入口（CRT 再调 <code>main</code>）。</p>',11)),(a(),n(p,null,{default:d(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXE%5B%22ELF%20%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E6%AE%B5%22%5D%0A%20%20MAP%20--%3E%20LD%5B%22ld.so%20%E5%8A%A0%E8%BD%BD%E4%BE%9D%E8%B5%96%22%5D%0A%20%20LD%20--%3E%20GOT%5B%22%E5%A1%AB%20GOT%20%2F%20PLT%22%5D%0A%20%20GOT%20--%3E%20ENT%5B%22%E8%BF%9B%E5%85%A5%E7%94%A8%E6%88%B7%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p><a href="/cs/abi-codegen">ABI 代码生成</a>发出的对外部符号的访问应是 PIC 友好的（<code>auipc</code>+GOT 等），否则共享库无法任意加载地址。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PIC：代码不假定自己的绝对加载址，用相对或 GOT。文本段可共享。写 GOT 使数据页私有（写时复制，OS 课再钉）。符号可见性（default/hidden）影响能否被插桩，点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核 <code>execve</code> 全部、不写容器命名空间。不把动态链接当安全课的 RELRO 清单——可点 ASLR 要 PIC，细节在安全栏。运行时堆与垃圾回收是下一课：加载完成后程序还要分配对象。</p><p>后课默认：进程启动可以经 <code>ld.so</code>；外部 C 符号可懒绑定。运行时与 GC 直觉接在可执行映像已经在内存之后。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>加载映射 ELF 段；动态链接器解析共享库。</li><li>GOT/PLT 把绑定推迟；PIC 使库可装到任意址。</li><li>ABI 必须与库一致。</li><li>出处：Levine, <em>Linkers and Loaders</em>, 2000；ELF；System V / RISC-V psABI。</li></ul>',8))])}const f=r(h,[["render",T]]);export{u as __pageData,f as default};
